// 定义数据类型
export interface Skill {
  name: string;
  percentage: number;
}

export interface Project {
  title: string;
  description: string; // 用于项目案例研究的痛点描述
  briefDescription?: string; // 用于精选项目的简短描述
  tech: string[];
  image: string;
  solution?: string;
  result?: string;
  link?: string;
}

export interface AITool {
  category: string;
  items: string[];
}

export interface WebsiteData {
  aboutMe: string;
  profilePhoto: string;
  skills: Skill[];
  projects: Project[];
  aiTools: AITool[];
  certificates: { image: string; title: string; description: string }[];
  githubLink?: string;
  heroTitle: string; // 英雄区域标题
  heroSubtitle: string; // 英雄区域副标题
}

